  List<Track> VisibleTracks(){if(Current==null)return new List<Track>();string q=songSearch.Text.Trim(),p=Convert.ToString(platformFilter.SelectedItem);return Current.Tracks.Where(t=>q.Length==0||(t.Title+" "+t.Artist+" "+t.Platform).IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).Where(t=>string.IsNullOrEmpty(p)||p=="全部平台"||(p=="本地音乐"?string.IsNullOrEmpty(t.Platform):t.Platform==p)).Where(t=>statusTab=="全部"||statusTab=="已完成"&&t.Status=="已完成"||statusTab=="历史复用"&&t.Status=="历史重复"||statusTab=="待处理"&&(t.Status=="待处理"||t.Status=="处理中"||t.Status=="待重新处理")||statusTab=="需补齐"&&(t.Status=="需要密钥"||t.Status=="待官方下载"||t.Status=="失败"||t.Status=="未支持"||t.Status=="待官方确认")).ToList();}
  void UpdateCounters(){var rows=playlists.SelectMany(p=>p.Tracks).ToList();int[] values={rows.Count,rows.Count(t=>t.Status=="已完成"),rows.Count(t=>t.Status=="历史重复"),rows.Count(t=>t.Status=="需要密钥"||t.Status=="待官方下载"||t.Status=="失败"||t.Status=="未支持"||t.Status=="待官方确认")};for(int i=0;i<4;i++)if(metricItems[i]!=null&&!metricItems[i].IsDisposed){metricItems[i].Value=values[i].ToString();metricItems[i].Invalidate();}storageCount.Text=store.History.Select(h=>h.RelativePath).Distinct().Count()+" 首";if(view=="歌单任务"){subtitle.Text=Current!=null&&!string.IsNullOrEmpty(Current.ImportNotice)?Current.ImportNotice:"保留每份源音质，整理成适合 Walkman 的音乐与播放列表。";subtitle.AutoEllipsis=true;tips.SetToolTip(subtitle,subtitle.Text);}selectionCaption.Text=playlists.Count+" 份歌单 · "+rows.Count+" 首，将处理全部歌单";}
  void SetView(bool cards){var selected=Selected;showCards=cards;if(selected!=null){if(cards)SelectCard(selected);else foreach(DataGridViewRow row in grid.Rows)if(row.DataBoundItem==selected){grid.CurrentCell=row.Cells[0];break;}}if(cardToggle!=null){cardToggle.Chosen=cards;cardToggle.Invalidate();tableToggle.Chosen=!cards;tableToggle.Invalidate();}UpdateStage(VisibleTracks().Count);}
  void UpdateStage(int count){if(taskStage==null||taskStage.IsDisposed)return;albumWall.Visible=showCards&&count>0;gridSurface.Visible=!showCards&&count>0;emptyState.Visible=count==0;if(count==0)emptyState.BringToFront();else if(showCards)albumWall.BringToFront();else gridSurface.BringToFront();}
  void BuildAlbumWall(List<Track> tracks){albumWall.SuspendLayout();foreach(Control c in albumWall.Controls.Cast<Control>().ToArray())c.Dispose();albumWall.Controls.Clear();if(cardSelected==null||!tracks.Contains(cardSelected))cardSelected=tracks.FirstOrDefault();int index=0;foreach(var t in tracks){var tile=new AlbumTile(t,FindCover(t),index++){Selected=t==cardSelected};tile.Activate=SelectCard;tile.Options=(track,control)=>{SelectCard(track);ShowSongMenu(control);};tips.SetToolTip(tile,t.Title+"\n"+t.Detail);albumWall.Controls.Add(tile);}albumWall.ResumeLayout();}
  void SelectCard(Track track){cardSelected=track;foreach(AlbumTile tile in albumWall.Controls.OfType<AlbumTile>()){tile.Selected=tile.Track==track;tile.Invalidate();}selectionCaption.Text="已选择："+track.Title+" · 右键可关联文件、补密钥或重试";}
