  string FindCover(Track t){if(!string.IsNullOrEmpty(t.OutputPath))try{string folder=Path.GetDirectoryName(Files.Inside(Path.Combine(store.Settings.OutputRoot,"Music"),t.OutputPath));foreach(string name in new[]{"container-cover.jpg","container-cover.png","cover.jpg","cover.png"}){string path=Path.Combine(folder,name);if(File.Exists(path))return path;}}catch{}if(!string.IsNullOrEmpty(t.SourcePath)){string path=Path.ChangeExtension(t.SourcePath,".jpg");if(File.Exists(path))return path;path=Path.ChangeExtension(t.SourcePath,".png");if(File.Exists(path))return path;}return null;}
